def _yaml_code(line):
    """`line` without its YAML comment. A comment starts at a `#` that begins the line or follows
    white space, OUTSIDE a quote: a `#` inside `' … '` or `" … "` is part of the value. In a
    single-quoted value `''` is a quote; in a double-quoted value `\\` escapes the next character.
    """
    quote, i = None, 0
    while i < len(line):
        c = line[i]
        if quote == "'":
            if c == "'":
                if line[i + 1:i + 2] == "'":
                    i += 2
                    continue
                quote = None
        elif quote == '"':
            if c == "\\":
                i += 2
                continue
            if c == '"':
                quote = None
        elif c in "'\"":
            quote = c
        elif c == "#" and (i == 0 or line[i - 1] in " \t"):
            return line[:i]
        i += 1
    return line


